import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";

export type SpinnerProps = HTMLAttributes<HTMLSpanElement> & {
  size?: "sm" | "md" | "lg";
  /** Announced to assistive tech. Default "Loading". */
  label?: string;
};

export function Spinner({ size = "md", label = "Loading", className, ...rest }: SpinnerProps) {
  return (
    <span {...rest} role="status" className={cx("hm-spinner", className)} data-size={size}>
      <span className="hm-sr-only">{label}</span>
    </span>
  );
}

export type SkeletonProps = HTMLAttributes<HTMLSpanElement> & {
  shape?: "text" | "block" | "circle";
  width?: string;
  height?: string;
};

/** A placeholder while content loads. A slow sheen, still under reduced motion. Hidden from assistive tech. */
export function Skeleton({ shape = "text", width, height, className, style, ...rest }: SkeletonProps) {
  return (
    <span
      aria-hidden="true"
      {...rest}
      className={cx("hm-skeleton", className)}
      data-shape={shape}
      style={{ width, height, ...style }}
    />
  );
}
